function o(){const e=()=>Math.random().toString(36).slice(2,7).toUpperCase();return`FDP-${e()}-${e()}`}async function t(e,r){if(await new Promise(n=>setTimeout(n,750)),!Number.isFinite(e)||e<100)return{ok:!1,error:"Montant minimum : 100 FCFA"};if(e>5e6)return{ok:!1,error:"Plafond Fedapay : 5 000 000 FCFA"};if(r.channel==="mobile"){if(!r.phone.trim())return{ok:!1,error:"Numéro Mobile Money requis"};if(!/^\d{4,6}$/.test(r.otp))return{ok:!1,error:"Code OTP invalide"}}else if(!/^\d{4}$/.test(r.last4))return{ok:!1,error:"Carte invalide"};return Math.random()<0?{ok:!1,error:"Fedapay : transaction refusée par l'émetteur"}:{ok:!0,reference:o(),processor:"fedapay",channel:r.channel}}export{t as chargeViaFedapay};
